rows = data_rows('Panel', {'J':'number', 'K':'string', 'L':'string', 'M':'string'}, 38, 50)
units = set(num('Panel', f'M{r}') for r in rows if cell('Panel', f'M{r}') not in [None, 'Incomplete'])
complete_units = []
for u in units:
    periods = [cell('Panel', f'K{r}') for r in rows if cell('Panel', f'M{r}') == u]
    if 'Pre' in periods and 'Post' in periods:
        complete_units.append(u)

# Group mean averages Outcome within that group and period across complete units (equal weight per unit)
# First, get per-unit, per-group, per-period values
unit_vals = {}
for u in complete_units:
    for g in ['Intervention', 'Reference']:
        for p in ['Pre', 'Post']:
            matches = [num('Panel', f'J{r}') for r in rows if cell('Panel', f'M{r}') == u and cell('Panel', f'L{r}') == g and cell('Panel', f'K{r}') == p]
            if matches:
                unit_vals[(u, g, p)] = sum(matches) / len(matches)

# Group mean across complete units
post_int = [unit_vals[(u, 'Intervention', 'Post')] for u in complete_units if (u, 'Intervention', 'Post') in unit_vals]
post_ref = [unit_vals[(u, 'Reference', 'Post')] for u in complete_units if (u, 'Reference', 'Post') in unit_vals]

mean_int = sum(post_int) / len(post_int) if post_int else 0
mean_ref = sum(post_ref) / len(post_ref) if post_ref else 0
result = round(mean_int - mean_ref, 2)

