import itertools
px = num('Unit profit', 'B38')
py = num('Unit profit', 'B39')
res = []
for r in [708, 709, 710]:
    cap = num('Resources', f'G{r}')
    yc = num('Resources', f'H{r}')
    xc = num('Resources', f'I{r}')
    res.append((cap, yc, xc))

best_profit = 0
# Test vertices and boundaries
points = [(0, 0)]
# intersection of constraints and axes
for (c1, y1, x1), (c2, y2, x2) in itertools.combinations(res, 2):
    det = x1 * y2 - x2 * y1
    if det != 0:
        x = (c1 * y2 - c2 * y1) / det
        y = (c2 * x1 - c1 * x2) / det
        if x >= 0 and y >= 0:
            points.append((x, y))
for c, y_c, x_c in res:
    if x_c != 0:
        points.append((c / x_c, 0))
    if y_c != 0:
        points.append((0, c / y_c))

for x, y in points:
    valid = True
    for c, y_c, x_c in res:
        if x_c * x + y_c * y > c + 1e-7:
            valid = False
            break
    if valid:
        profit = px * x + py * y
        if profit > best_profit:
            best_profit = profit

result = round(best_profit, 2)

